"""Core column-oriented table data structure."""

from __future__ import annotations

from typing import Any, Dict, Iterable, Iterator, List, Mapping, Optional, Sequence


class Table:
    """A table of column-oriented data.

    A :class:`Table` stores an ordered set of columns, each backed by a list of
    values of equal length. Missing values are represented by ``None``.

    Instances are treated as immutable by convention: every operation that
    transforms a table returns a new :class:`Table` rather than mutating the
    original.
    """

    def __init__(
        self,
        columns: Sequence[str],
        data: Optional[Mapping[str, Sequence[Any]]] = None,
    ) -> None:
        columns = list(columns)
        if len(set(columns)) != len(columns):
            raise ValueError("column names must be unique")

        data = {} if data is None else data
        normalized: Dict[str, List[Any]] = {}
        length: Optional[int] = None
        for name in columns:
            values = list(data.get(name, []))
            if length is None:
                length = len(values)
            elif len(values) != length:
                raise ValueError(
                    "all columns must have the same length "
                    f"(column {name!r} has {len(values)}, expected {length})"
                )
            normalized[name] = values

        self._columns = columns
        self._data = normalized
        self._length = 0 if length is None else length

    # ------------------------------------------------------------------
    # Constructors
    # ------------------------------------------------------------------
    @classmethod
    def from_rows(
        cls,
        columns: Sequence[str],
        rows: Iterable[Sequence[Any]],
    ) -> "Table":
        """Build a table from row-oriented data."""
        columns = list(columns)
        data: Dict[str, List[Any]] = {name: [] for name in columns}
        for index, row in enumerate(rows):
            values = list(row)
            if len(values) != len(columns):
                raise ValueError(
                    f"row {index} has {len(values)} values, expected {len(columns)}"
                )
            for name, value in zip(columns, values):
                data[name].append(value)
        return cls(columns, data)

    @classmethod
    def from_dicts(
        cls,
        records: Iterable[Mapping[str, Any]],
        columns: Optional[Sequence[str]] = None,
    ) -> "Table":
        """Build a table from an iterable of row dictionaries.

        When ``columns`` is omitted the column order is the order in which keys
        first appear across the records. Missing keys are filled with ``None``.
        """
        records = list(records)
        if columns is None:
            seen: Dict[str, None] = {}
            for record in records:
                for key in record:
                    seen.setdefault(key, None)
            columns = list(seen)

        columns = list(columns)
        data: Dict[str, List[Any]] = {name: [] for name in columns}
        for record in records:
            for name in columns:
                data[name].append(record.get(name))
        return cls(columns, data)

    # ------------------------------------------------------------------
    # Basic properties
    # ------------------------------------------------------------------
    @property
    def columns(self) -> List[str]:
        """The column names, in order."""
        return list(self._columns)

    @property
    def num_rows(self) -> int:
        return self._length

    @property
    def num_columns(self) -> int:
        return len(self._columns)

    @property
    def shape(self) -> tuple:
        """Return ``(num_rows, num_columns)``."""
        return (self._length, len(self._columns))

    def __len__(self) -> int:
        return self._length

    def __contains__(self, name: object) -> bool:
        return name in self._data

    def __getitem__(self, name: str) -> List[Any]:
        return self.column(name)

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return self.rows(named=True)

    # ------------------------------------------------------------------
    # Access
    # ------------------------------------------------------------------
    def column(self, name: str) -> List[Any]:
        """Return a copy of the values for ``name``."""
        if name not in self._data:
            raise KeyError(f"unknown column: {name!r}")
        return list(self._data[name])

    def row(self, index: int) -> Dict[str, Any]:
        """Return a single row as a dictionary."""
        if index < 0:
            index += self._length
        if not 0 <= index < self._length:
            raise IndexError("row index out of range")
        return {name: self._data[name][index] for name in self._columns}

    def rows(self, named: bool = False) -> Iterator[Any]:
        """Iterate over rows as lists, or dictionaries when ``named`` is true."""
        for index in range(self._length):
            if named:
                yield self.row(index)
            else:
                yield [self._data[name][index] for name in self._columns]

    def to_dicts(self) -> List[Dict[str, Any]]:
        """Return the table as a list of row dictionaries."""
        return list(self.rows(named=True))

    def head(self, n: int = 5) -> "Table":
        """Return a new table with the first ``n`` rows."""
        n = max(0, n)
        return self._slice(0, min(n, self._length))

    def tail(self, n: int = 5) -> "Table":
        """Return a new table with the last ``n`` rows."""
        n = max(0, n)
        return self._slice(max(0, self._length - n), self._length)

    def _slice(self, start: int, stop: int) -> "Table":
        data = {name: values[start:stop] for name, values in self._data.items()}
        return Table(self._columns, data)

    # ------------------------------------------------------------------
    # Transformation
    # ------------------------------------------------------------------
    def select(self, columns: Sequence[str]) -> "Table":
        """Return a new table containing only ``columns``."""
        return Table(columns, {name: self.column(name) for name in columns})

    def drop(self, columns: Sequence[str]) -> "Table":
        """Return a new table without ``columns``."""
        drop = set(columns)
        missing = drop.difference(self._data)
        if missing:
            raise KeyError(f"unknown columns: {sorted(missing)!r}")
        keep = [name for name in self._columns if name not in drop]
        return Table(keep, {name: self.column(name) for name in keep})

    def rename(self, mapping: Mapping[str, str]) -> "Table":
        """Return a new table with columns renamed according to ``mapping``."""
        unknown = set(mapping).difference(self._data)
        if unknown:
            raise KeyError(f"unknown columns: {sorted(unknown)!r}")
        new_columns = [mapping.get(name, name) for name in self._columns]
        data = {
            mapping.get(name, name): self.column(name) for name in self._columns
        }
        return Table(new_columns, data)

    def with_column(self, name: str, values: Sequence[Any]) -> "Table":
        """Return a new table with ``name`` added or replaced."""
        values = list(values)
        if len(values) != self._length:
            raise ValueError(
                f"column {name!r} has {len(values)} values, expected {self._length}"
            )
        data = {col: self.column(col) for col in self._columns}
        data[name] = values
        columns = self._columns if name in self._data else self._columns + [name]
        return Table(columns, data)

    def filter(self, predicate) -> "Table":
        """Return a new table with rows for which ``predicate(row_dict)`` is true."""
        keep = [row for row in self.rows(named=True) if predicate(row)]
        return Table.from_dicts(keep, columns=self._columns)

    # ------------------------------------------------------------------
    # Comparison / display
    # ------------------------------------------------------------------
    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self._columns == other._columns and self._data == other._data

    def __repr__(self) -> str:
        return (
            f"Table(columns={self._columns!r}, rows={self._length}, "
            f"cols={len(self._columns)})"
        )

"""Reading and writing CSV files."""

from __future__ import annotations

import csv
import io
import os
import re
from contextlib import contextmanager
from typing import Any, Iterable, Iterator, List, Optional, Sequence, TextIO, Union

from .table import Table

DEFAULT_MISSING = ("", "na", "n/a", "nan", "null", "none")

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$")

PathLike = Union[str, "os.PathLike[str]"]


def infer_value(value: Any) -> Any:
    """Infer a Python type for a raw string value.

    Empty/missing tokens become ``None``. Integer and float literals are
    converted to ``int``/``float``, ``true``/``false`` to ``bool`` and
    everything else is left as a string. Strings with leading zeros (for
    example ``"007"``) are preserved as strings to avoid losing information.
    """
    if value is None:
        return None
    if not isinstance(value, str):
        return value

    token = value.strip()
    lowered = token.lower()
    if lowered in DEFAULT_MISSING:
        return None
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    if _INT_RE.match(token):
        digits = token.lstrip("+-")
        if len(digits) > 1 and digits.startswith("0"):
            return token
        return int(token)
    if _FLOAT_RE.match(token):
        return float(token)
    return value


def coerce_value(value: Any, target: str) -> Any:
    """Coerce ``value`` to the type named by ``target``.

    Supported targets: ``"str"``, ``"int"``, ``"float"``, ``"bool"`` and
    ``"auto"`` (infer). ``None`` is preserved for all targets. Values that
    cannot be converted raise :class:`ValueError`.
    """
    if value is None:
        return None

    target = target.lower()
    if target == "auto":
        return infer_value(value)
    if target == "str":
        return value if isinstance(value, str) else str(value)
    if target == "int":
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, str):
            value = value.strip()
            if validate_missing(value):
                return None
        return int(float(value)) if isinstance(value, str) and "." in value else int(value)
    if target == "float":
        if isinstance(value, str):
            value = value.strip()
            if validate_missing(value):
                return None
        return float(value)
    if target == "bool":
        if isinstance(value, bool):
            return value
        token = str(value).strip().lower()
        if token in ("true", "1", "yes", "y"):
            return True
        if token in ("false", "0", "no", "n"):
            return False
        raise ValueError(f"cannot convert {value!r} to bool")
    raise ValueError(f"unknown type target: {target!r}")


def validate_missing(token: str) -> bool:
    return token.strip().lower() in DEFAULT_MISSING


@contextmanager
def _open_source(source: Union[PathLike, TextIO], encoding: str) -> Iterator[TextIO]:
    if hasattr(source, "read"):
        yield source  # type: ignore[misc]
        return
    with open(source, "r", encoding=encoding, newline="") as handle:
        yield handle


def _unique_columns(names: Sequence[str]) -> List[str]:
    result: List[str] = []
    seen = {}
    for name in names:
        candidate = name
        if candidate in seen:
            seen[candidate] += 1
            candidate = f"{name}_{seen[name]}"
            while candidate in seen:
                seen[name] += 1
                candidate = f"{name}_{seen[name]}"
        seen[candidate] = 0
        result.append(candidate)
    return result


def read_csv(
    source: Union[PathLike, TextIO],
    delimiter: str = ",",
    encoding: str = "utf-8",
    header: bool = True,
    infer_types: bool = True,
    skip_blank_lines: bool = True,
    missing_values: Optional[Iterable[str]] = None,
) -> Table:
    """Load a CSV file into a :class:`~tabular.table.Table`.

    Parameters
    ----------
    source:
        A filesystem path or an already-open text file object.
    delimiter:
        Field delimiter.
    header:
        When true the first non-blank row provides column names, otherwise
        columns are named ``col_1`` ... ``col_n``.
    infer_types:
        When true, numeric/boolean/missing values are inferred, otherwise all
        values remain strings.
    skip_blank_lines:
        Ignore rows whose cells are all empty.
    missing_values:
        Extra tokens (in addition to the defaults) treated as missing.
    """
    missing = set(DEFAULT_MISSING)
    if missing_values:
        missing.update(token.strip().lower() for token in missing_values)

    with _open_source(source, encoding) as handle:
        reader = csv.reader(handle, delimiter=delimiter)
        rows = []
        for raw in reader:
            if skip_blank_lines and all(cell.strip() == "" for cell in raw):
                continue
            rows.append(raw)

    if not rows:
        columns = [] if header else []
        return Table(columns, {})

    width = max(len(row) for row in rows)
    if header:
        header_row = rows[0]
        header_row = header_row + [""] * (width - len(header_row))
        columns = _unique_columns(
            [name.strip() if name.strip() else f"col_{i + 1}" for i, name in enumerate(header_row)]
        )
        body = rows[1:]
    else:
        columns = [f"col_{i + 1}" for i in range(width)]
        body = rows

    data: dict = {name: [] for name in columns}
    for row in body:
        padded = row + [""] * (width - len(row))
        for name, cell in zip(columns, padded):
            if infer_types:
                value = infer_value(cell)
            else:
                stripped = cell.strip()
                value = None if stripped.lower() in missing else cell
            data[name].append(value)

    return Table(columns, data)


def read_csv_string(
    text: str,
    **kwargs: Any,
) -> Table:
    """Convenience wrapper around :func:`read_csv` for CSV content in a string."""
    kwargs.pop("encoding", None)
    return read_csv(io.StringIO(text), **kwargs)


def write_csv(
    table: Table,
    destination: Union[PathLike, TextIO],
    delimiter: str = ",",
    encoding: str = "utf-8",
    include_header: bool = True,
) -> None:
    """Write ``table`` to a CSV file.

    ``destination`` may be a filesystem path or a writable text file object.
    ``None`` values are written as empty fields.
    """
    close = False
    if hasattr(destination, "write"):
        handle = destination  # type: ignore[assignment]
    else:
        handle = open(destination, "w", encoding=encoding, newline="")
        close = True

    try:
        writer = csv.writer(handle, delimiter=delimiter)
        if include_header:
            writer.writerow(table.columns)
        for row in table.rows():
            writer.writerow(["" if value is None else value for value in row])
    finally:
        if close:
            handle.close()

"""Cleaning and normalisation operations.

Every function returns a new :class:`~tabular.table.Table`; the input table is
never modified.
"""

from __future__ import annotations

import re
from typing import Any, Callable, Iterable, List, Mapping, Optional, Sequence

from .io import coerce_value
from .table import Table

_NON_WORD = re.compile(r"[^\w]+")

# Aggregation helpers -------------------------------------------------------

def _mean(values: Sequence[float]) -> float:
    return sum(values) / len(values)


def _median(values: Sequence[float]) -> float:
    ordered = sorted(values)
    n = len(ordered)
    mid = n // 2
    if n % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2


def _mode(values: Sequence[Any]) -> Any:
    counts: dict = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    if not counts:
        return None
    return max(counts, key=counts.get)


# Operations ----------------------------------------------------------------

def strip_whitespace(table: Table, columns: Optional[Sequence[str]] = None) -> Table:
    """Strip leading/trailing whitespace from string cells."""
    targets = table.columns if columns is None else list(columns)
    for name in targets:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")
    data = {}
    for name in table.columns:
        values = table.column(name)
        if name in targets:
            values = [value.strip() if isinstance(value, str) else value for value in values]
        data[name] = values
    return Table(table.columns, data)


def normalize_column_names(table: Table, case: str = "lower") -> Table:
    """Normalise column names to ``snake_case``, de-duplicating as needed.

    ``case`` may be ``"lower"``, ``"upper"`` or ``None``.
    """
    rename: dict = {}
    used: dict = {}
    for name in table.columns:
        cleaned = _NON_WORD.sub("_", str(name).strip()).strip("_")
        if not cleaned:
            cleaned = "column"
        if case == "lower":
            cleaned = cleaned.lower()
        elif case == "upper":
            cleaned = cleaned.upper()
        elif case is not None:
            raise ValueError("case must be 'lower', 'upper' or None")
        candidate = cleaned
        if candidate in used:
            used[candidate] += 1
            candidate = f"{cleaned}_{used[candidate]}"
        used.setdefault(candidate, 0)
        rename[name] = candidate
    return table.rename(rename)


def drop_missing(
    table: Table,
    columns: Optional[Sequence[str]] = None,
    how: str = "any",
) -> Table:
    """Drop rows containing missing values.

    ``how`` is ``"any"`` (drop when any selected value is missing) or ``"all"``
    (drop only when all selected values are missing).
    """
    if how not in ("any", "all"):
        raise ValueError("how must be 'any' or 'all'")
    targets = table.columns if columns is None else list(columns)
    for name in targets:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")

    keep = []
    for row in table.rows(named=True):
        missing = [row[name] is None for name in targets]
        should_drop = any(missing) if how == "any" else all(missing)
        if not should_drop:
            keep.append(row)
    return Table.from_dicts(keep, columns=table.columns)


def fill_missing(
    table: Table,
    value: Any = None,
    columns: Optional[Sequence[str]] = None,
    strategy: str = "value",
) -> Table:
    """Fill missing values.

    Strategies:

    ``"value"``
        Replace missing values with ``value``.
    ``"mean"`` / ``"median"``
        Replace with the column mean/median (numeric columns only).
    ``"mode"``
        Replace with the most common non-missing value.
    ``"ffill"`` / ``"bfill"``
        Forward/backward fill within the column.
    """
    valid = {"value", "mean", "median", "mode", "ffill", "bfill"}
    if strategy not in valid:
        raise ValueError(f"strategy must be one of {sorted(valid)!r}")
    targets = table.columns if columns is None else list(columns)
    for name in targets:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")

    data = {}
    for name in table.columns:
        values = table.column(name)
        if name not in targets:
            data[name] = values
            continue
        data[name] = _fill_column(values, value, strategy)
    return Table(table.columns, data)


def _fill_column(values: List[Any], value: Any, strategy: str) -> List[Any]:
    present = [v for v in values if v is not None]
    if strategy == "value":
        replacement = value
    elif strategy == "mode":
        replacement = _mode(present)
    elif strategy in ("mean", "median"):
        numeric = [v for v in present if isinstance(v, (int, float)) and not isinstance(v, bool)]
        if not numeric:
            raise ValueError(f"cannot compute {strategy} of non-numeric column")
        replacement = _mean(numeric) if strategy == "mean" else _median(numeric)
    elif strategy == "ffill":
        result = []
        last = value
        for item in values:
            if item is None:
                result.append(last)
            else:
                result.append(item)
                last = item
        return result
    else:  # bfill
        result = []
        last = value
        for item in reversed(values):
            if item is None:
                result.append(last)
            else:
                result.append(item)
                last = item
        return list(reversed(result))

    return [replacement if item is None else item for item in values]


def drop_duplicates(
    table: Table,
    columns: Optional[Sequence[str]] = None,
    keep: str = "first",
) -> Table:
    """Remove duplicate rows.

    ``keep`` is ``"first"``, ``"last"`` or ``False`` (drop every duplicated
    row).
    """
    targets = table.columns if columns is None else list(columns)
    for name in targets:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")
    if keep not in ("first", "last", False, None):
        raise ValueError("keep must be 'first', 'last' or False")

    indexed = []
    seen: dict = {}
    for position, row in enumerate(table.rows(named=True)):
        key = tuple(row[name] for name in targets)
        indexed.append((key, position, row))
        seen.setdefault(key, []).append(position)

    keep_positions = set()
    for key, positions in seen.items():
        if keep == "first":
            keep_positions.add(positions[0])
        elif keep == "last":
            keep_positions.add(positions[-1])
        # keep in (False, None) -> drop all duplicated positions

    ordered = sorted(keep_positions)
    return Table.from_dicts([indexed[i][2] for i in ordered], columns=table.columns)


def convert_types(table: Table, schema: Mapping[str, str]) -> Table:
    """Convert columns to the types described by ``schema``.

    ``schema`` maps a column name to one of ``"str"``, ``"int"``, ``"float"``,
    ``"bool"`` or ``"auto"``.
    """
    unknown = set(schema).difference(table.columns)
    if unknown:
        raise KeyError(f"unknown columns: {sorted(unknown)!r}")
    data = {}
    for name in table.columns:
        values = table.column(name)
        if name in schema:
            values = [coerce_value(value, schema[name]) for value in values]
        data[name] = values
    return Table(table.columns, data)


def replace_values(
    table: Table,
    replacements: Mapping[Any, Any],
    columns: Optional[Sequence[str]] = None,
) -> Table:
    """Replace values in ``columns`` according to ``replacements``."""
    targets = table.columns if columns is None else list(columns)
    for name in targets:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")
    data = {}
    for name in table.columns:
        values = table.column(name)
        if name in targets:
            values = [replacements.get(value, value) for value in values]
        data[name] = values
    return Table(table.columns, data)


def filter_rows(table: Table, predicate: Callable[[Mapping[str, Any]], bool]) -> Table:
    """Keep only rows for which ``predicate`` returns a truthy value."""
    return Table.from_dicts(
        [row for row in table.rows(named=True) if predicate(row)],
        columns=table.columns,
    )

"""Statistical analysis and aggregation helpers."""

from __future__ import annotations

import math
from typing import Any, Callable, Dict, List, Mapping, Optional, Sequence, Union

from .table import Table

Number = Union[int, float]


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def numeric_values(values: Sequence[Any]) -> List[Number]:
    """Return only the numeric (non-boolean, non-missing) values."""
    return [value for value in values if _is_number(value)]


def mean(values: Sequence[Any]) -> Optional[float]:
    """Arithmetic mean, or ``None`` when there are no numeric values."""
    numbers = numeric_values(values)
    return sum(numbers) / len(numbers) if numbers else None


def median(values: Sequence[Any]) -> Optional[float]:
    """Median, or ``None`` when there are no numeric values."""
    numbers = sorted(numeric_values(values))
    n = len(numbers)
    if not n:
        return None
    mid = n // 2
    if n % 2:
        return float(numbers[mid])
    return (numbers[mid - 1] + numbers[mid]) / 2


def variance(values: Sequence[Any]) -> Optional[float]:
    """Sample variance (``n - 1`` denominator), or ``None`` for fewer than 2."""
    numbers = numeric_values(values)
    n = len(numbers)
    if n < 2:
        return None
    avg = sum(numbers) / n
    return sum((value - avg) ** 2 for value in numbers) / (n - 1)


def stdev(values: Sequence[Any]) -> Optional[float]:
    """Sample standard deviation, or ``None`` for fewer than 2 values."""
    var = variance(values)
    return math.sqrt(var) if var is not None else None


def minimum(values: Sequence[Any]) -> Any:
    present = [value for value in values if value is not None]
    try:
        return min(present) if present else None
    except TypeError:
        return None


def maximum(values: Sequence[Any]) -> Any:
    present = [value for value in values if value is not None]
    try:
        return max(present) if present else None
    except TypeError:
        return None


def total(values: Sequence[Any]) -> Optional[float]:
    numbers = numeric_values(values)
    return sum(numbers) if numbers else None


def quantile(values: Sequence[Any], q: float) -> Optional[float]:
    """Linear-interpolation quantile (``q`` in ``[0, 1]``)."""
    if not 0.0 <= q <= 1.0:
        raise ValueError("q must be between 0 and 1")
    numbers = sorted(numeric_values(values))
    if not numbers:
        return None
    if len(numbers) == 1:
        return float(numbers[0])
    position = q * (len(numbers) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return float(numbers[int(position)])
    fraction = position - lower
    return numbers[lower] * (1 - fraction) + numbers[upper] * fraction


def value_counts(
    table: Table,
    column: str,
    normalize: bool = False,
    dropna: bool = True,
) -> Dict[Any, float]:
    """Count occurrences of each value in ``column``, most frequent first."""
    values = table.column(column)
    counts: Dict[Any, int] = {}
    for value in values:
        if value is None and dropna:
            continue
        counts[value] = counts.get(value, 0) + 1
    ordered = dict(sorted(counts.items(), key=lambda item: item[1], reverse=True))
    if normalize:
        denom = sum(ordered.values())
        return {key: count / denom for key, count in ordered.items()} if denom else {}
    return ordered


def correlation(table: Table, column_x: str, column_y: str) -> Optional[float]:
    """Pearson correlation between two numeric columns.

    Returns ``None`` when fewer than two complete pairs exist or either column
    has zero variance.
    """
    xs = table.column(column_x)
    ys = table.column(column_y)
    pairs = [
        (x, y)
        for x, y in zip(xs, ys)
        if _is_number(x) and _is_number(y)
    ]
    n = len(pairs)
    if n < 2:
        return None
    mean_x = sum(pair[0] for pair in pairs) / n
    mean_y = sum(pair[1] for pair in pairs) / n
    cov = sum((x - mean_x) * (y - mean_y) for x, y in pairs)
    var_x = sum((x - mean_x) ** 2 for x, _ in pairs)
    var_y = sum((y - mean_y) ** 2 for _, y in pairs)
    if var_x == 0 or var_y == 0:
        return None
    return cov / math.sqrt(var_x * var_y)


def _mode(values: Sequence[Any]) -> Any:
    counts: Dict[Any, int] = {}
    for value in values:
        if value is None:
            continue
        counts[value] = counts.get(value, 0) + 1
    if not counts:
        return None
    return max(counts, key=counts.get)


def _first(values: Sequence[Any]) -> Any:
    for value in values:
        if value is not None:
            return value
    return None


def _last(values: Sequence[Any]) -> Any:
    for value in reversed(values):
        if value is not None:
            return value
    return None


def _nunique(values: Sequence[Any]) -> int:
    return len({value for value in values if value is not None})


_AGGREGATORS: Dict[str, Callable[[Sequence[Any]], Any]] = {
    "count": lambda values: sum(1 for value in values if value is not None),
    "size": len,
    "sum": total,
    "mean": mean,
    "median": median,
    "stdev": stdev,
    "variance": variance,
    "min": minimum,
    "max": maximum,
    "mode": _mode,
    "first": _first,
    "last": _last,
    "nunique": _nunique,
}


def _resolve_aggregator(spec: Union[str, Callable[[Sequence[Any]], Any]]):
    if callable(spec):
        return spec, getattr(spec, "__name__", "agg")
    if spec not in _AGGREGATORS:
        raise ValueError(
            f"unknown aggregation {spec!r}; expected one of {sorted(_AGGREGATORS)!r}"
        )
    return _AGGREGATORS[spec], spec


def summary(table: Table, columns: Optional[Sequence[str]] = None) -> Dict[str, Dict[str, Any]]:
    """Return per-column summary statistics as ``{column: {stat: value}}``."""
    targets = table.columns if columns is None else list(columns)
    result: Dict[str, Dict[str, Any]] = {}
    for name in targets:
        values = table.column(name)
        present = [value for value in values if value is not None]
        result[name] = {
            "count": len(present),
            "missing": len(values) - len(present),
            "unique": _nunique(values),
            "mean": mean(values),
            "median": median(values),
            "stdev": stdev(values),
            "min": minimum(values),
            "max": maximum(values),
            "mode": _mode(values),
        }
    return result


_STAT_COLUMNS = [
    "column",
    "count",
    "missing",
    "unique",
    "mean",
    "median",
    "stdev",
    "min",
    "max",
    "mode",
]


def describe(table: Table, columns: Optional[Sequence[str]] = None) -> Table:
    """Return a table of summary statistics, one row per column."""
    stats = summary(table, columns)
    rows = []
    for name, values in stats.items():
        row = {"column": name}
        row.update(values)
        rows.append(row)
    return Table.from_dicts(rows, columns=_STAT_COLUMNS)


def group_by(
    table: Table,
    by: Union[str, Sequence[str]],
    aggregations: Optional[Mapping[str, Union[str, Callable, Sequence]]] = None,
) -> Table:
    """Group rows by one or more columns and aggregate.

    ``aggregations`` maps a source column to an aggregation name, a callable,
    or a sequence of either (for example ``{"sales": ["mean", "max"]}``). When
    omitted, only a ``count`` of rows per group is produced.
    """
    by_columns = [by] if isinstance(by, str) else list(by)
    if not by_columns:
        raise ValueError("at least one grouping column is required")
    for name in by_columns:
        if name not in table:
            raise KeyError(f"unknown column: {name!r}")

    plan: List[tuple] = []
    if aggregations is None:
        plan.append((by_columns[0], "count", "count"))
    else:
        for source, spec in aggregations.items():
            if source not in table:
                raise KeyError(f"unknown column: {source!r}")
            specs = [spec] if isinstance(spec, str) or callable(spec) else list(spec)
            for item in specs:
                func, label = _resolve_aggregator(item)
                plan.append((source, func, f"{source}_{label}"))

    groups: Dict[tuple, List[Mapping[str, Any]]] = {}
    order: List[tuple] = []
    for row in table.rows(named=True):
        key = tuple(row[name] for name in by_columns)
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(row)

    rows = []
    for key in order:
        members = groups[key]
        row: Dict[str, Any] = dict(zip(by_columns, key))
        for source, func, output in plan:
            row[output] = func([member[source] for member in members])
        rows.append(row)

    output_columns = list(by_columns) + [item[2] for item in plan]
    return Table.from_dicts(rows, columns=output_columns)

